   468→   468→+	t.Chdir(dir)
   469→   469→+	paths.ClearWorktreeRootCache()
   470→   470→+
   471→   471→+	s := &ManualCommitStrategy{}
   472→   472→+
   473→   473→+	// First PostCommit: force-condenses all 76 stale ENDED sessions.
   474→   474→+	if err := s.PostCommit(context.Background()); err != nil {
   475→   475→+		t.Fatalf("first PostCommit: %v", err)
   476→   476→+	}
   477→   477→+
   478→   478→+	// Verify all sessions are FullyCondensed — the core invariant of the fix.
   479→   479→+	for i := range reportedSessionCount {
   480→   480→+		sessionID := fmt.Sprintf("ended-session-%d", i)
   481→   481→+		state, err := s.loadSessionState(context.Background(), sessionID)
   482→   482→+		if err != nil {
   483→   483→+			t.Errorf("load state session %d: %v", i, err)
   484→   484→+			continue
   485→   485→+		}
   486→   486→+		if state == nil {
   487→   487→+			t.Errorf("session %d state missing after first PostCommit", i)
   488→   488→+			continue
   489→   489→+		}
   490→   490→+		if !state.FullyCondensed {
   491→   491→+			t.Errorf("session %d: FullyCondensed = false, want true", i)
   492→   492→+		}
   493→   493→+		if state.StepCount != 0 {
   494→   494→+			t.Errorf("session %d: StepCount = %d, want 0", i, state.StepCount)
   495→   495→+		}
   496→   496→+		if len(state.FilesTouched) != 0 {
   497→   497→+			t.Errorf("session %d: FilesTouched = %v, want empty", i, state.FilesTouched)
   498→   498→+		}
   499→   499→+	}
   500→   500→+
   501→   501→+	// Create a second commit to feed to the next PostCommit.
   502→   502→+	repo, err := git.PlainOpen(dir)
   503→   503→+	if err != nil {
   504→   504→+		t.Fatalf("open repo: %v", err)
   505→   505→+	}
   506→   506→+	wt, err := repo.Worktree()
   507→   507→+	if err != nil {
   508→   508→+		t.Fatalf("worktree: %v", err)
   509→   509→+	}
   510→   510→+	f := filepath.Join(dir, "second_commit.txt")
   511→   511→+	if err := os.WriteFile(f, []byte("second commit"), 0o644); err != nil {
   512→   512→+		t.Fatalf("write: %v", err)
   513→   513→+	}
   514→   514→+	if _, err := wt.Add("second_commit.txt"); err != nil {
   515→   515→+		t.Fatalf("add: %v", err)
   516→   516→+	}
   517→   517→+	cpID, err := id.Generate()
   518→   518→+	if err != nil {
   519→   519→+		t.Fatalf("generate ID: %v", err)
   520→   520→+	}
   521→   521→+	commitMsg := fmt.Sprintf("second commit\n\n%s: %s\n", trailers.CheckpointTrailerKey, cpID)
   522→   522→+	if _, err := wt.Commit(commitMsg, &git.CommitOptions{
   523→   523→+		Author: &object.Signature{Name: "User", Email: "user@test.com", When: time.Now()},
   524→   524→+	}); err != nil {
   525→   525→+		t.Fatalf("commit: %v", err)
   526→   526→+	}
   527→   527→+	paths.ClearWorktreeRootCache()
   528→   528→+
   529→   529→+	// Second PostCommit: all 76 sessions are FullyCondensed → skipped.
   530→   530→+	// This is the commit that took 2m44s before the fix.
   531→   531→+	// 2 seconds is a generous upper bound; the fix makes this ~10ms.
   532→   532→+	s2 := &ManualCommitStrategy{}
   533→   533→+	start := time.Now()
   534→   534→+	if err := s2.PostCommit(context.Background()); err != nil {
   535→   535→+		t.Fatalf("second PostCommit: %v", err)
   536→   536→+	}
   537→   537→+	elapsed := time.Since(start)
   538→   538→+
   539→   539→+	if elapsed > 2*time.Second {
   540→   540→+		t.Errorf("second PostCommit with %d FullyCondensed sessions took %v — "+
   541→   541→+			"regression in issue #591 fix? Expected < 2s", reportedSessionCount, elapsed)
   542→   542→+	}
   543→   543→+	t.Logf("second PostCommit with %d FullyCondensed sessions: %v", reportedSessionCount, elapsed)
   544→   544→+}
