   598→   598→+	if err != nil {
   599→   599→+		return fmt.Errorf("failed to load session state: %w", err)
   600→   600→+	}
   601→   601→+	if state == nil {
   602→   602→+		return nil // No state file
   603→   603→+	}
   604→   604→+
   605→   605→+	// Sessions with FilesTouched must be processed by PostCommit for carry-forward
   606→   606→+	// tracking — each user commit that overlaps with tracked files gets its own
   607→   607→+	// checkpoint. Eagerly condensing here would prevent that 1:1 linkage.
   608→   608→+	if len(state.FilesTouched) > 0 {
   609→   609→+		return nil
   610→   610→+	}
   611→   611→+
   612→   612→+	// Only condense if there's uncondensed data
   613→   613→+	if state.StepCount <= 0 {
   614→   614→+		// No data and no files — mark FullyCondensed
   615→   615→+		state.FullyCondensed = true
   616→   616→+		return s.saveSessionState(ctx, state)
   617→   617→+	}
