    20→// BenchmarkPostCommit_EndedSessionAccumulation measures the PostCommit overhead
    21→// caused by accumulated ENDED sessions whose files don't overlap with the committed
    22→// files. This is the exact scenario from GitHub issue #591.
    23→//
    24→// On main (before fix): each ENDED session adds ~73-103ms per commit, forever.
    25→// After fix: first commit force-condenses all, subsequent commits skip them.
    26→func BenchmarkPostCommit_EndedSessionAccumulation(b *testing.B) {
    27→	for _, count := range []int{10, 50, 100, 200} {
    28→		b.Run(fmt.Sprintf("EndedSessions_%d", count), benchEndedSessionAccumulation(count, repoProfileSmall))
    29→	}
    30→}
    31→
    32→// BenchmarkPostCommit_RepoProfiles measures PostCommit with 50 accumulated ENDED
    33→// sessions across different repository profiles.
    34→func BenchmarkPostCommit_RepoProfiles(b *testing.B) {
    35→	for _, profile := range []struct {
    36→		name string
    37→		fn   repoProfile
    38→	}{
    39→		{"SmallRepo_100files", repoProfileSmall},
    40→		{"LargeFiles_50x20MB", repoProfileLargeFiles},
    41→		// 500k files takes too long to set up for benchmarks; use 1000 as proxy
    42→		{"ManyFiles_1000", repoProfileManyFiles},
    43→	} {
    44→		b.Run(profile.name, benchEndedSessionAccumulation(50, profile.fn))
    45→	}
    46→}
