    48→// BenchmarkPostCommit_SecondCommitAfterFix measures the key metric: how fast is
    49→// the SECOND commit after force-condensation cleaned up all ENDED sessions?
    50→// On main: same as first commit (sessions persist). After fix: near-zero overhead.
    51→func BenchmarkPostCommit_SecondCommitAfterFix(b *testing.B) {
    52→	for _, count := range []int{50, 100, 200} {
    53→		b.Run(fmt.Sprintf("SecondCommit_%dEndedSessions", count), func(b *testing.B) {
    54→			for range b.N {
    55→				b.StopTimer()
    56→				dir := setupAccumulationRepo(b, count, repoProfileSmall)
    57→				b.Chdir(dir)
    58→				paths.ClearWorktreeRootCache()
    59→
    60→				// First PostCommit: processes all ENDED sessions
    61→				s := &ManualCommitStrategy{}
    62→				if err := s.PostCommit(context.Background()); err != nil {
    63→					b.Fatalf("PostCommit 1: %v", err)
    64→				}
    65→
    66→				// Create another commit for the second PostCommit
    67→				repo, err := git.PlainOpen(dir)
    68→				if err != nil {
    69→					b.Fatalf("open: %v", err)
    70→				}
    71→				wt, err := repo.Worktree()
    72→				if err != nil {
    73→					b.Fatalf("worktree: %v", err)
    74→				}
    75→				newFile := filepath.Join(dir, "second_commit.txt")
    76→				if err := os.WriteFile(newFile, []byte("second commit content"), 0o644); err != nil {
    77→					b.Fatalf("write: %v", err)
    78→				}
    79→				if _, err := wt.Add("second_commit.txt"); err != nil {
    80→					b.Fatalf("add: %v", err)
    81→				}
    82→				cpID, err := id.Generate()
    83→				if err != nil {
    84→					b.Fatalf("generate ID: %v", err)
    85→				}
    86→				commitMsg := fmt.Sprintf("second commit\n\n%s: %s\n", trailers.CheckpointTrailerKey, cpID)
